package all

import (
	"github.com/bluenviron/gomavlib/v4/pkg/dialects/development"
)

// Source of manual control input currently selected by the autopilot's manual control arbitration.
type MAV_MANUAL_INPUT_SOURCE = development.MAV_MANUAL_INPUT_SOURCE

const (
	// No manual input messages are currently being provided.
	MAV_MANUAL_INPUT_SOURCE_NONE MAV_MANUAL_INPUT_SOURCE = development.MAV_MANUAL_INPUT_SOURCE_NONE
	// Manual input messages are being provided by a radio control (RC) receiver.
	MAV_MANUAL_INPUT_SOURCE_RC MAV_MANUAL_INPUT_SOURCE = development.MAV_MANUAL_INPUT_SOURCE_RC
	// Manual input messages are being provided by a MAVLink enabled input device (e.g. via MANUAL_CONTROL messages). The specific device is identified by the sender_system_id and sender_component_id fields.
	MAV_MANUAL_INPUT_SOURCE_MAVLINK MAV_MANUAL_INPUT_SOURCE = development.MAV_MANUAL_INPUT_SOURCE_MAVLINK
	// Manual input messages are being provided simultaneously by both a radio control (RC) receiver and a MAVLink enabled input device.
	MAV_MANUAL_INPUT_SOURCE_MIXED MAV_MANUAL_INPUT_SOURCE = development.MAV_MANUAL_INPUT_SOURCE_MIXED
)
